"""Structured Task Plan Schema generated by Master Agent."""
from typing import List, Optional
from datetime import datetime
from pydantic import BaseModel, Field, model_validator
from src.models.common import Contract


class StagePlan(Contract):
    stage_id: str
    stage_name: str
    assigned_agent: str
    dependencies: List[str] = Field(default_factory=list)
    description: str
    validation_gate: str


class TaskPlan(Contract):
    project_id: str
    plan_version: str = "v1"
    summary: str
    theme: str
    genre: str
    mood: str
    stages: List[StagePlan] = Field(min_length=1)
    estimated_duration_seconds: int
    key_constraints: List[str] = Field(default_factory=list)
    raw_model_response: Optional[str] = None
    created_at: str = Field(default_factory=lambda: datetime.utcnow().isoformat() + "Z")

    @model_validator(mode="after")
    def validate_dependencies(self):
        seen = set()
        for stage in self.stages:
            if stage.stage_id in seen or any(dep not in seen for dep in stage.dependencies):
                raise ValueError("计划依赖必须唯一、无环且按拓扑顺序排列")
            seen.add(stage.stage_id)
        if not {"MasterAgent", "LyricsAgent", "AudioAgent", "HumanReviewer"}.issubset({s.assigned_agent for s in self.stages}):
            raise ValueError("计划必须包含主 Agent、作词、音频与人工审核阶段")
        sequence = [stage.assigned_agent for stage in self.stages]
        required = ["LyricsAgent", "HumanReviewer", "AudioAgent", "HumanReviewer", "MasterAgent"]
        position = 0
        for agent in sequence:
            if position < len(required) and agent == required[position]:
                position += 1
        if position != len(required):
            raise ValueError("计划必须按作词、歌词人工审核、作曲、音频人工审核、交付的顺序排列")
        return self
